INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(22401, 'Matthew 12:27', 'Matthew', 12, 27, '&nbsp;نو کۀ چرې زۀ پيريان د بعلزبول په مدد شړم نو ستاسو مريدان يې د چا په وسيله شړى؟ نو په هم دې وجه به هغوئ تاسو ملامته کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22402, 'Matthew 12:28', 'Matthew', 12, 28, '&nbsp;خو کۀ زۀ دا پيريان د خُدائ پاک د روح په مدد شړم نو د خُدائ پاک بادشاهى ستاسو په مينځ کښې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22403, 'Matthew 12:29', 'Matthew', 12, 29, '&nbsp;بيا څنګه يو سړے د يو زورَور سړى په کور ورتلے شى او د هغۀ مال حال لوټ کولے شى؟ ترڅو چې اول هغۀ دا زورَور سړے تړلے نۀ وى د هغۀ کور نۀ شى لوټ کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22404, 'Matthew 12:30', 'Matthew', 12, 30, '&nbsp;څوک چې ما سره نۀ دے، هغه زما خلاف دے. څوک يې چې ما سره يو ځائ نۀ راټولوى نو هغه يې نولى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22405, 'Matthew 12:31', 'Matthew', 12, 31, '&nbsp;نو ځکه زۀ تاسو ته دا وايم چې يوه ګناه او يو کُفر داسې نشته چې د بنى آدمو بخښلے نۀ شى، سېوا د هغه کُفر نه چې د روحُ القُدس په خلاف لګولے شوے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22406, 'Matthew 12:32', 'Matthew', 12, 32, '&nbsp;هر څوک چې د اِبن آدم خلاف څۀ وائى هغه به وبخښلے شى، خو هر هغه څوک چې د روحُ القُدس په خلاف خبرې کوى هغه به نۀ په دې دُنيا کښې او نۀ په بله دُنيا کښې وبخښلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22407, 'Matthew 12:33', 'Matthew', 12, 33, '&nbsp;يا خو ونه او د هغې مېوه ښۀ وګڼئ او يا ونه او د هغې مېوه بده وګڼئ، ځکه چې تاسو ونه د هغې په مېوه پېژندلے شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22408, 'Matthew 12:34', 'Matthew', 12, 34, '&nbsp;اے د مارانو بچو، ستاسو خبرې څنګه ښې کېدے شى چې په خپله تاسو ښۀ نۀ يئ؟ ځکه چې کومې خبرې چې په خولۀ راځى هغه د زړۀ نه راوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22409, 'Matthew 12:35', 'Matthew', 12, 35, '&nbsp;ښۀ سړے د زړۀ د خزانې نه نېکى راوباسى او بد سړے چې د زړۀ خزانه يې بده وى هغه ترې بدى راوباسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22410, 'Matthew 12:36', 'Matthew', 12, 36, '&nbsp;زۀ تاسو ته دا وايم، هر څوک چې څۀ فضول خبرې هم کوى نو د قيامت په ورځ به ورسره د هغې حساب کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22411, 'Matthew 12:37', 'Matthew', 12, 37, '&nbsp;ځکه چې تاسو به په خپلو خبرو سره صادق يا ګناه ګار ثابت شئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22412, 'Matthew 12:38', 'Matthew', 12, 38, '&nbsp;ځينې د شرعې عالمانو او فريسيانو ووئيل چې، ”اُستاذه، مونږ غواړُو چې تۀ مونږ ته د نښې په توګه معجزه وښائې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22413, 'Matthew 12:39', 'Matthew', 12, 39, '&nbsp;هغۀ ورته جواب ورکړو، ”دا يوه بدکاره او زناکاره پيړۍ ده چې نښې غواړى خو د يُونس نبى د نښې نه سېوا يوه نښه به هم دوئ ته ورنۀ کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22414, 'Matthew 12:40', 'Matthew', 12, 40, '&nbsp;نو لکه څنګه چې يُونس د کب په ګېډه کښې درې ورځې او درې شپې تېرې کړې نو دغه شان به اِبن آدم هم درې ورځې او درې شپې د زمکې په تَل کښې تېرې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22415, 'Matthew 12:41', 'Matthew', 12, 41, '&nbsp;د نينوه خلق به هم د دې زمانې د خلقو په خلاف د قيامت په ورځ ودريږى او دا پيړۍ به مجرمه ثابته کړى ځکه چې هغوئ د يُونس په بيان توبه ګار شوى وُو، او اوس څوک چې دلته دے، هغه د يُونس نه لوئ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22416, 'Matthew 12:42', 'Matthew', 12, 42, '&nbsp;د جنوب مَلِکه به د قيامت په ورځ د دې پيړۍ خلاف په عدالت کښې ودريږى او دوئ به مجرمان ثابت کړى، ځکه چې هغه د دُنيا د بل ګوټ نه د سليمان د حِکمت خبرو اورېدو له راغلې وه، او څوک چې دلته دے هغه د سليمان نه هم لوئ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22417, 'Matthew 12:43', 'Matthew', 12, 43, '&nbsp;هرکله چې د يو کس نه پيرے بهر شى نو هغه په صحراګانو سر شى چې آرام ومومى، خو وې نۀ مومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22418, 'Matthew 12:44', 'Matthew', 12, 44, '&nbsp;نو هغه بيا داسې ووائى چې زۀ به واپس هغه کور ته لاړ شم د کوم نه چې راوتلے يم. نو هغه چې واپس راشى نو هغه کور صرف جارُو کړے او د اوسېدو جوګه بيا مومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22419, 'Matthew 12:45', 'Matthew', 12, 45, '&nbsp;بيا هغه لاړ شى او نور اووۀ پيريان د ځان سره راولى چې د دۀ نه هم زيات خراب وى او هغوئ ټول راشى او په پيرى نيولى کس دېره شى، او د هغۀ اَنجام د پخوا نه هم لا خراب شى. نو دغه حال به هم د دې نافرمانه پيړۍ وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22420, 'Matthew 12:46', 'Matthew', 12, 46, '&nbsp;عيسىٰ لا د خلقو سره په خبرو لګيا وو چې د هغۀ خپله مور او وروڼه بهر ولاړ وُو او غوښتل يې چې د هغۀ سره خبرې وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22421, 'Matthew 12:47', 'Matthew', 12, 47, '&nbsp;په دې کښې چا هغۀ ته ووئيل چې، ”ستا مور او وروڼه بهر ولاړ دى، هغوئ تا سره مِلاوېدل غواړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22422, 'Matthew 12:48', 'Matthew', 12, 48, '&nbsp;عيسىٰ هغه سړى ته وفرمائيل چې، ”زما مور څوک ده؟ او زما وروڼه څوک دى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22423, 'Matthew 12:49', 'Matthew', 12, 49, '&nbsp;نو بيا هغۀ خپلو مريدانو ته اِشاره وکړه او وې فرمائيل چې، ”زما مور او زما وروڼه دا دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22424, 'Matthew 12:50', 'Matthew', 12, 50, '&nbsp;ځکه هر هغه څوک چې زما د آسمانى پلار رضا کوى، هغه زما ورور، خور او مور ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22425, 'Matthew 13:1', 'Matthew', 13, 1, '&nbsp;هم په دغه ورځ عيسىٰ د کور نه بهر شو او د درياب په غاړه کښېناستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22426, 'Matthew 13:2', 'Matthew', 13, 2, '&nbsp;او دومره ډېر خلق ورته راټول شوى وُو چې هغه ترې کشتۍ ته وختلو او هلته کښېناستو او ټول خلق ورته د درياب په غاړه ودرېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22427, 'Matthew 13:3', 'Matthew', 13, 3, '&nbsp;هغۀ هغوئ ته ډيرې خبرې په مِثالونو کښې وکړې. هغۀ ورته وفرمائيل چې، ”واورئ، يو زميندار د کروندې دپاره بهر لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22428, 'Matthew 13:4', 'Matthew', 13, 4, '&nbsp;نو چې کله هغۀ په خپل پټى کښې تخم نوستلو نو څۀ تخم ترې نه په لاره پرېوتو نو مارغان راغلل هغه يې وخوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22429, 'Matthew 13:5', 'Matthew', 13, 5, '&nbsp;څۀ تخم په کاڼيزه زمکه پرېوتو چرته چې لږه شان خاوره وه او دا زر راوټوکېدلو خو چې هلته لاندې نوره خاوره نۀ وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22430, 'Matthew 13:6', 'Matthew', 13, 6, '&nbsp;خو چې نمر راوختلو نو هغه بوټى يې وسوزول او هغه اوچ شُو ځکه چې جرړې يې نۀ وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22431, 'Matthew 13:7', 'Matthew', 13, 7, '&nbsp;څۀ تخم په غنو کښې پرېوتو، ازغى لوئ شول او فصل يې لاندې کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22432, 'Matthew 13:8', 'Matthew', 13, 8, '&nbsp;او څۀ تخم په زرخيزه زمکه پرېوتو او غله يې وکړه، ځينې يو په سل، ځينې يو په شپېتۀ او ځينې يو په دېرش.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22433, 'Matthew 13:9', 'Matthew', 13, 9, '&nbsp;کۀ څوک د اورېدو غوږونه لرى هغه دې واورى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22434, 'Matthew 13:10', 'Matthew', 13, 10, '&nbsp;مريدان عيسىٰ ته ورنزدې شول او تپوس يې ترې وکړو چې، ”تۀ دوئ ته په مِثالونو کښې خبرې ولې کوې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22435, 'Matthew 13:11', 'Matthew', 13, 11, '&nbsp;هغۀ جواب ورکړو، ”تاسو له دا موقع درکړے شوې ده چې د آسمان د بادشاهۍ په رازونو پوهه شئ، خو هغه نورو ته نۀ ده ورکړے شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22436, 'Matthew 13:12', 'Matthew', 13, 12, '&nbsp;ځکه چې د هر چا سره چې څۀ وى هغۀ له به نور هم ورکړے شى تر دې چې ورسره لا زيات شى، خو د چا سره چې څۀ نۀ وى هغۀ نه به هغه څۀ هم واخستلے شى چې ورسره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22437, 'Matthew 13:13', 'Matthew', 13, 13, '&nbsp;ځکه زۀ هغوئ ته په مِثالونو کښې خبرې کوم، ځکه چې، ”هغوئ ګورى خو وينى نه، اورى خو پوهيږى نه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22438, 'Matthew 13:14', 'Matthew', 13, 14, '&nbsp;په هغوئ کښې د يشعياه نبى يوه پېشګوئې پوره کيږى چې وائى، ”تاسو به يې بيا بيا اورئ خو پوهېږئ به پرې نه، تاسو به يې په سترګو وينئ خو رسېږئ به پرې نه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22439, 'Matthew 13:15', 'Matthew', 13, 15, '&nbsp;ځکه چې د دې اُمت زړونه سخت شوى دى، غوږونه يې کاڼۀ شوى او سترګې يې پټې شوې دى. ګنې د هغوئ سترګو خو به ليدل، د هغوئ غوږونو به اورېدل او د هغوئ زړونه به پوهېدل، او بيا به هغوئ واپس راګرځېدلى وے او ما به روغ کړى وے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22440, 'Matthew 13:16', 'Matthew', 13, 16, '&nbsp;خو ستاسو سترګې بختورې دى ځکه چې وينئ، او ستاسو غوږونه بختور دى ځکه چې اورئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22441, 'Matthew 13:17', 'Matthew', 13, 17, '&nbsp;زۀ تاسو ته رښتيا وايم چې د ډېرو نبيانو او زبرګانو دا ارمان وو چې هغه څۀ ووينى څۀ چې تاسو وينئ خو هغوئ ونۀ ليدل، او هغه څۀ واورى چې تاسو يې اوس اورئ خو هغوئ وانۀ ورېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22442, 'Matthew 13:18', 'Matthew', 13, 18, '&nbsp;نو بيا د زميندار مِثال واورئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22443, 'Matthew 13:19', 'Matthew', 13, 19, '&nbsp;کله چې يو کس د خُدائ پاک د بادشاهۍ کلام اورى خو پوهيږى پرې نه، نو شېطان راشى او هغه څۀ ترې هم وباسى څۀ چې د هغۀ په زړۀ کښې کَرلے شوى وى، دا هغه څۀ دى څۀ چې په لاره کَرلے شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22444, 'Matthew 13:20', 'Matthew', 13, 20, '&nbsp;په کاڼيزه زمکه د کَرلے شوى تخم مِثال د هغه چا دے چې هر کله چې کلام واورى نو په خوشحالۍ سره يې سمدستى قبول کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22445, 'Matthew 13:21', 'Matthew', 13, 21, '&nbsp;خو چې جرړې يې نۀ وى، نو د زغم طاقت په کښې د لږ وخت دپاره وى، نو بيا کله چې د کلام په وجه په هغوئ تکليف يا سختى راشى نو بيا سمدستى هغوئ تيندک وخورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22446, 'Matthew 13:22', 'Matthew', 13, 22, '&nbsp;په غنو کښې د پرېوتلى تخم مِثال د هغه چا دے څوک چې کلام واورى خو دُنيادارى او د دولت مينه په دۀ غالبه شى او کلام بې‌مېوې پاتې شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22447, 'Matthew 13:23', 'Matthew', 13, 23, '&nbsp;خو کوم تخم چې په زرخيزه زمکه پرېوځى د دې مِثال د هغه چا دے څوک چې کلام اورى، پرې پوهه شى او يو په دېرش، يو په شپېتۀ او يو په سل مېوه راوړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22448, 'Matthew 13:24', 'Matthew', 13, 24, '&nbsp;عيسىٰ يو بل مِثال هغوئ ته وړاندې کړو چې، ”د آسمان بادشاهى داسې ده چې يو سړے په خپل پټى کښې ښۀ تخم وکَرى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22449, 'Matthew 13:25', 'Matthew', 13, 25, '&nbsp;او کله چې څوک اودۀ وى او دشمن يې راشى او په هغه زمکه ورته د غنمو سره جمدر هم وکَرى او لاړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22450, 'Matthew 13:26', 'Matthew', 13, 26, '&nbsp;هر کله چې فصل زرغون شى او وَږى وباسى نو جمدر په کښې ښکاره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22451, 'Matthew 13:27', 'Matthew', 13, 27, '&nbsp;او د زميندار نوکران خپل مالِک له لاړ شى او ورته وائى، نېکه، په کوم پټى کښې چې تاسو ښۀ تخم کَرلے وو هغه خو اوس د جمدرو نه ډک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22452, 'Matthew 13:28', 'Matthew', 13, 28, '&nbsp;هغه په جواب کښې وائى چې دا د دشمن کارونه دى. بيا هغوئ ووائى چې، مونږ لاړ شُو او دغه جمدر ترې وکاږو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22453, 'Matthew 13:29', 'Matthew', 13, 29, '&nbsp;هغۀ جواب ورکړو چې، نه، کله چې تاسو جمدر وکاږئ هسې نه چې غنم هم ورسره وکاږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22454, 'Matthew 13:30', 'Matthew', 13, 30, '&nbsp;پرېږدئ چې دواړه يو ځائ پاخۀ شى، نو د لَو په وخت به زۀ لَوګرو ته ووايم چې اول جمدر وريبئ او د سوزولو دپاره يې ګېډۍ کړئ، پس له هغې نه غنم وريبئ او زما درمند ته يې راوړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22455, 'Matthew 13:31', 'Matthew', 13, 31, '&nbsp;او يو بل مِثال عيسىٰ هغوئ ته وړاندې کړو چې، ”د آسمان د بادشاهۍ مِثال د شړشمو د هغه تخم په شان دے کوم چې يو سړى راواخستو او په خپل پټى کښې يې وکَرلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22456, 'Matthew 13:32', 'Matthew', 13, 32, '&nbsp;دا تخم اګر چې د ټولو تخمونو نه ورکوټے وى خو کله چې دا لوئ شى نو دا د باغ د هرې بلې کروندې نه لوئ شى، او داسې بوټے شى چې د هوا مارغان راځى او د هغې په څانګو کښېنى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22457, 'Matthew 13:33', 'Matthew', 13, 33, '&nbsp;عيسىٰ ورته دا مِثال هم ورکړو چې، ”د آسمان بادشاهى د خمبيرې په شان ده چې يوې ښځې راواخسته او په درېو قلپو اوړو کښې يې ګډه کړه نو بيا هغه درې واړه خمبيره شوې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22458, 'Matthew 13:34', 'Matthew', 13, 34, '&nbsp;عيسىٰ هغه خلقو ته دا ټولې خبرې په مِثالونو کښې وکړې او رښتيا خو دا دى چې يوه خبره يې هم بې‌مثاله ونۀ کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22459, 'Matthew 13:35', 'Matthew', 13, 35, '&nbsp;دا د نبى د پېشګويۍ تصديق وو چې، ”زۀ به د خبرو شروع په مِثالونو سره وکړم، او هغه خبرې به څرګندې کړم چې د دُنيا د پېدايښت راسې پټې ساتلے شوې دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22460, 'Matthew 13:36', 'Matthew', 13, 36, '&nbsp;هغۀ بيا خلق رُخصت کړل او کور ته ورننوتو او مريدان ورله راغلل او ورته يې ووئيل چې، ”مونږ په پټى کښې د جمدر په مِثال پوهه کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22461, 'Matthew 13:37', 'Matthew', 13, 37, '&nbsp;هغۀ په جواب کښې وفرمائيل چې، ”اِبن آدم زميندار دے څوک چې ښۀ تخم کَرى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22462, 'Matthew 13:38', 'Matthew', 13, 38, '&nbsp;پټے دا دُنيا ده، ښۀ تخم د بادشاهۍ اولاد دے او جمدر د شېطان اولاد دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22463, 'Matthew 13:39', 'Matthew', 13, 39, '&nbsp;او هغه دشمن چا چې جمدر کَرلى دى هغه اِبليس دے، لو د قيامت ورځ ده او لَوګرى فرښتې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22464, 'Matthew 13:40', 'Matthew', 13, 40, '&nbsp;لکه څنګه چې جمدر په آخره کښې راټولولے شى او په اور کښې سوزولے کيږى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22465, 'Matthew 13:41', 'Matthew', 13, 41, '&nbsp;دغه شان په آخره کښې به اِبن آدم خپلې فرښتې ولېږى او د هغۀ د بادشاهۍ نه به هر هغه څيز راغونډ کړى چې سړے پرې تيندک خورى او هغه ټول خلق چې بې‌شرعې کارونه کوى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22466, 'Matthew 13:42', 'Matthew', 13, 42, '&nbsp;دوئ به د اور بټۍ ته وغورزوى يعنې هغه ځائ ته چرته به چې ژړا او د غاښونو چيچل وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22467, 'Matthew 13:43', 'Matthew', 13, 43, '&nbsp;او بيا به صادقان د خپل پلار په بادشاهۍ کښې لکه د نمر ځليږى. څوک چې غوږونه لرى نو هغه دې واورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22468, 'Matthew 13:44', 'Matthew', 13, 44, '&nbsp;د آسمان بادشاهى د هغه خزانې په مِثال ده چې په پټى کښې پټه وى. کوم سړى چې دا وموندله نو بيا يې ښخه کړه او په خوشحالۍ يې خپل هر څۀ خرڅ کړل او هغه پټے يې پرې واخستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22469, 'Matthew 13:45', 'Matthew', 13, 45, '&nbsp;د آسمان د بادشاهۍ دا يو بل مِثال دے چې يو سوداګر د ښو ملغلرو په تلاش کښې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22470, 'Matthew 13:46', 'Matthew', 13, 46, '&nbsp;هغۀ يوه ډېره غوره ملغلره وموندله او د هغې د حاصلولو دپاره يې خپل هر څۀ خرڅ کړل او هغه يې واخسته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22471, 'Matthew 13:47', 'Matthew', 13, 47, '&nbsp;بيا د آسمان بادشاهى د هغه جال په شان ده چې سمندر ته واچولے شو او په کښې رنګارنګ ماهيان راګېر شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22472, 'Matthew 13:48', 'Matthew', 13, 48, '&nbsp;هر کله چې ډک شو نو غاړې ته يې راښکلو، نو بيا سړى ورته کښېناستل او ښۀ ماهيان يې ترې نه جدا کړل او په ټوکرو کښې يې واچول او خراب يې ترې وغورزول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22473, 'Matthew 13:49', 'Matthew', 13, 49, '&nbsp;دغسې به د قيامت ورځ وى، فرښتې به ورشى او نېکان به د بدکارانو نه راجدا کړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22474, 'Matthew 13:50', 'Matthew', 13, 50, '&nbsp;او بدکاران به د اور بټۍ ته وغورزوى، يعنې هغه ځائ ته چرته به چې ژړا او د غاښونو چيچل وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22475, 'Matthew 13:51', 'Matthew', 13, 51, '&nbsp;عيسىٰ ورنه تپوس وکړو چې، ”ولې تاسو په دې ټولو خبرو ورسېدئ؟“ او هغوئ دا جواب ورکړو چې، ”آو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22476, 'Matthew 13:52', 'Matthew', 13, 52, '&nbsp;بيا هغۀ دوئ ته وفرمائيل، ”هرکله چې د آسمان په بادشاهۍ کښې يو اُستاذ زده کړې ته کښېناستو نو هغه د کور د مالِک په مِثال دے، څوک چې د خپل ګودام نه زاړۀ او نوى څيزونه راوباسى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22477, 'Matthew 13:53', 'Matthew', 13, 53, '&nbsp;څۀ وخت چې عيسىٰ د مِثالونو بيان ختم کړو نو هغه د هغه ځائ نه روان شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22478, 'Matthew 13:54', 'Matthew', 13, 54, '&nbsp;او خپل ښار ته راغلو چرته چې هغۀ خلقو ته د هغوئ په عبادتخانو کښې تعليم ورکولو. نو هغوئ حېران شول او تپوس يې ترې وکړو چې، ”دا حکمت او د معجزو طاقت يې له کومه ځايه حاصل کړے دے؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22479, 'Matthew 13:55', 'Matthew', 13, 55, '&nbsp;ولې دے د ترکاڼ زوئ نۀ دے؟ ولې د دۀ مور مريم نۀ ده او د دۀ وروڼه يعقوب، يوسف، شمعون او يهوداه نۀ دى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22480, 'Matthew 13:56', 'Matthew', 13, 56, '&nbsp;او ولې د دۀ ټولې خوېندې دلته زمونږ سره نۀ دى څۀ؟ نو بيا دا حکمت دۀ چرته زده کړے دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22481, 'Matthew 13:57', 'Matthew', 13, 57, '&nbsp;دغه شان هغوئ هغه رد کړو. خو عيسىٰ په دې وينا مجبور شو چې، ”د نبى په هر ځائ کښې عزت وى بغېر د خپل ښار او د خپلو خپلوانو او د خپل خاندان نه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22482, 'Matthew 13:58', 'Matthew', 13, 58, '&nbsp;هغۀ هلته زياتې معجزې ښکاره نۀ کړې ځکه چې د هغوئ ايمان نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22483, 'Matthew 14:1', 'Matthew', 14, 1, '&nbsp;هم په دغه ورځو کښې هيروديس چې د ګليل ګورنر وو، کله چې د عيسىٰ د کارونو نه خبر شو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22484, 'Matthew 14:2', 'Matthew', 14, 2, '&nbsp;نو هغۀ خپلو نوکرانو ته ووئيل چې، ”بې‌شکه چې دا بپتسمه ورکوونکے يحيىٰ دے. هغه د مړو نه راژوندے شوے دے، ځکه خو ورسره د معجزو طاقت هم دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22485, 'Matthew 14:3', 'Matthew', 14, 3, '&nbsp;ځکه هيروديس د خپل ورور فيليپوس د ښځې هيرودياس په وجه يحيىٰ ګرفتار کړے وو، په زنځير يې تړلے وو او په قېدخانه کښې يې اچولے وو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22486, 'Matthew 14:4', 'Matthew', 14, 4, '&nbsp;په دې وجه چې يحيىٰ هغۀ ته فرمائيلى وُو چې، ”د دې سره نِکاح کول په تا حرام دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22487, 'Matthew 14:5', 'Matthew', 14, 5, '&nbsp;هيروديس به هغه مړ کړے وو خو د خلقو نه يرېدلو ځکه چې خلقو هغه نبى ګڼلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22488, 'Matthew 14:6', 'Matthew', 14, 6, '&nbsp;خو د هيروديس د سالګرې په ورځ د هيرودياس لور د مېلمنو په وړاندې داسې وګډېدله او هيروديس دومره زيات خوشحاله شو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
