(22490, 'Matthew 14:8', 'Matthew', 14, 8, '&nbsp;د مور په وينا هغې ووئيل چې، ”ما له دلته د بپتسمه ورکوونکى يحيىٰ سر په تالى کښې راوړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22491, 'Matthew 14:9', 'Matthew', 14, 9, '&nbsp;بادشاه چې دا واورېدل نو غمژن شو، خو د خپلو قسمونو او مېلمنو په وجه هغۀ دا حُکم وکړو چې دا خواست دې پوره کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
