(22493, 'Matthew 14:11', 'Matthew', 14, 11, '&nbsp;نو د هغۀ سر يې په تالى کښې ورله راوړو او جينۍ له يې ورکړو او هغې خپلې مور له يوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22494, 'Matthew 14:12', 'Matthew', 14, 12, '&nbsp;بيا د يحيىٰ مريدان راغلل او د هغۀ لاش يې واخستو او ښخ يې کړو. او هغوئ لاړل او عيسىٰ ته يې حال ووې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22495, 'Matthew 14:13', 'Matthew', 14, 13, '&nbsp;کله چې عيسىٰ دا خبر واورېدو نو په يوه کِشتۍ کښې هغه د هغه ځايه يو خوشى بيابان ته لاړو چې يواځې وى. خو خلق خبر شُو او په دۀ پسې د ښارونو نه پياده روان شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22496, 'Matthew 14:14', 'Matthew', 14, 14, '&nbsp;هغه چې غاړې ته راورسېدو نو يوه لويه ګڼه يې وليده، زړۀ يې پرې وسوزېدو او چې په کښې څوک بيماران وُو هغه يې روغ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22497, 'Matthew 14:15', 'Matthew', 14, 15, '&nbsp;کله چې ماښام شو د هغۀ مريدان هغۀ له ورغلل او وې وئيل چې، ”دا خوشے بيابان دے او ناوخته دے، خلق کلو ته رُخصت کړه چې لاړ شى چې خپل ځان له د خوراک څۀ څيزونه واخلى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22498, 'Matthew 14:16', 'Matthew', 14, 16, '&nbsp;خو عيسىٰ جواب ورکړو، ”د دوئ د تلو حاجت نشته، تاسو د ځانه دوئ ته د خوراک څۀ ورکړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22499, 'Matthew 14:17', 'Matthew', 14, 17, '&nbsp;هغوئ ووئيل چې، ”مونږ سره دلته نور څۀ نشته خو پينځۀ روټۍ او دوه کبان دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22500, 'Matthew 14:18', 'Matthew', 14, 18, '&nbsp;هغۀ وفرمائيل، ”دا ما له راوړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');